arguments.file_text:
@page "/chat"
@using sv_b72e521f26fb42c282fd32cf35fef247.Components.Pages.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(threadOpen ? "thread-visible" : "")">
    <ChannelList Channels="channels"
                 SelectedChannelId="selectedChannelId"
                 OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@currentChannelName"
                 ChannelDescription="@currentChannelDescription"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 IsLoadingMore="isLoadingMore"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage"
                 OnLoadMore="LoadMoreMessages" />

    @if (threadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = [];
    private int selectedChannelId;
    private string currentChannelName = "";
    private string currentChannelDescription = "";

    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    private bool isLoadingMore;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        var channel = channels.First(c => c.Id == channelId);
        currentChannelName = channel.Name;
        currentChannelDescription = channel.Description;

        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channelId);
        BuildThreadSummaries();

        // Update unread count locally
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channel with { UnreadCount = 0 };
        }

        CloseThread();
    }

    private async Task SendMessage(string content)
    {
        var sent = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(sent);
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            BuildThreadSummaries();
        }

        isLoadingMore = false;
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update thread summary
        threadSummaries[threadRootMessage.Id] = new ThreadSummary(
            threadRootMessage.Id, threadReplies.Count, reply.SentAt);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistic update
        var msg = messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
        }
    }

    private void BuildThreadSummaries()
    {
        threadSummaries = [];
        var replies = messages.Where(m => m.ReplyToId.HasValue).GroupBy(m => m.ReplyToId!.Value);
        foreach (var group in replies)
        {
            threadSummaries[group.Key] = new ThreadSummary(
                group.Key, group.Count(), group.Max(m => m.SentAt));
        }
    }
}

/* Chat layout — three-panel responsive design */

.chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: calc(100vh - 3.5rem);
    overflow: hidden;
}

.chat-layout.thread-visible {
    grid-template-columns: 20% 1fr 25%;
}

/* Channel List (Left Sidebar) */
.channel-list {
    background: #2b2d42;
    color: #edf2f4;
    overflow-y: auto;
    padding: 1rem 0;
    border-right: 1px solid #1a1b2e;
}

.channel-list-header {
    padding: 0 1rem 0.75rem;
    font-size: 0.85rem;
